{
  "name": "@jacobwolf/opencode-subagent-router",
  "version": "0.5.0",
  "description": "Route simple OpenCode subagent tasks to faster models with Jev.",
  "keywords": [
    "jev",
    "opencode",
    "plugin",
    "routing",
    "subagent"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/JacobNWolf/opencode-subagent-router.git"
  },
  "bin": {
    "opencode-subagent-router": "./bin/install.mjs"
  },
  "files": [
    "bin",
    "src",
    "README.md",
    "LICENSE"
  ],
  "type": "module",
  "main": "./src/index.ts",
  "module": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts",
    "./server": "./src/index.ts"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "fmt": "oxfmt",
    "fmt:check": "oxfmt --check",
    "lint": "oxlint",
    "lint:ts": "oxlint --type-check",
    "typecheck": "tsc --noEmit",
    "test": "bun test",
    "test:coverage": "bun test --coverage"
  },
  "dependencies": {
    "@opencode-ai/models": "^0.0.87",
    "arkregex": "^0.0.10",
    "effect": "4.1.0",
    "es-toolkit": "^1.52.0",
    "jsonc-morph": "^0.4.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.31",
    "@opencode/plugin": "2.2.6",
    "@types/bun": "latest",
    "oxfmt": "^0.68.0",
    "oxlint": "^1.83.0",
    "oxlint-tsgolint": "^7.0.2002",
    "typescript": "^7"
  },
  "engines": {
    "node": ">=20",
    "opencode": ">=1.18.31"
  }
}
